function getPrtgTranslation(key, lang) {
    if (prtgTranslations[lang] && prtgTranslations[lang][key]) {
        return prtgTranslations[lang][key];
    }
    if (prtgTranslations.en && prtgTranslations.en[key]) {
        return prtgTranslations.en[key];
    }
    return null;
}

function applyPrtgTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.prtg.')) {
            const translation = getPrtgTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyPrtgTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyPrtgTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyPrtgTranslations(currentLang);
}


